// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer maker;
    FakeERC20 token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(
        uint256 duration,
        uint256 premium,
        uint256 strike,
        uint256 nonce,
        uint256 warpOffset
    ) public {
        // admissible domain: duration must be < 10_000 days, positive offsets fine
        duration = bound(duration, 1 days, 9_000 days);
        premium = bound(premium, 1, 1e30);
        strike = bound(strike, 0, 1e30);
        warpOffset = bound(warpOffset, 0, 1_000_000_000);
        vm.warp(1_700_000_000 + warpOffset);

        maker = new Signer();
        token = new FakeERC20();

        PuttyV2.Order memory order;
        order.maker = address(maker);
        order.isCall = true;
        order.isLong = false; // short order: P stores expiry under opposite (long) positionId
        order.baseAsset = address(token);
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = block.timestamp + 10_000;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new PuttyV2.ERC20Asset[](0);
        order.erc721Assets = new PuttyV2.ERC721Asset[](0);

        // 65-byte signature whose ecrecover fails (v=0) -> falls back to IERC1271
        bytes memory sig = new bytes(65);
        uint256[] memory floors = new uint256[](0);

        vm.prank(address(this));
        c.fillOrder(order, sig, floors);

        uint256 shortPositionId = uint256(c.hashOppositeOrder(order));
        assertTrue(
            c.positionExpirations(shortPositionId) == block.timestamp + duration,
            "short position expiration must be recorded under the opposite positionId"
        );
    }
}

contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

contract FakeERC20 {
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
